<script setup lang="ts">import {ref,onMounted} from 'vue';import {useRoute} from 'vue-router';import {useResearch} from '../stores/research';import {useAuth} from '../stores/auth';import {createCampaign,approveCampaign,exportCampaign} from '../api/campaigns';import {useTask} from '../hooks/useTask';import PageHeading from '../components/common/PageHeading.vue';import ErrorNotice from '../components/common/ErrorNotice.vue';import StatusBadge from '../components/common/StatusBadge.vue';import EmptyState from '../components/common/EmptyState.vue';const route=useRoute(),store=useResearch(),auth=useAuth(),name=ref('冬季复学 · 进度回顾'),segment=ref(Number(route.query.segment)||0),note=ref('先交付个人学习进度回顾，再邀请参与冬季复学；14 天后复盘。'),{busy,error,perform}=useTask();onMounted(()=>perform(async()=>{await store.load();if(!segment.value)segment.value=store.segments[0]?.id||0;}));function submit(){perform(async()=>{await createCampaign({name:name.value,segment_id:segment.value,note:note.value});await store.load();name.value='';});}function approve(id:number){perform(async()=>{await approveCampaign(id);await store.load();});}</script><template><PageHeading eyebrow="ACTION / APPROVED AUDIENCE DELIVERY" title="从研究，走到一次合适的触达" description="研究员拟定方案，负责人批准；阅读者可下载已批准的匿名名单。"/><ErrorNotice :message="error" @retry="perform(store.load)"/><div class="campaign-layout"><form v-if="auth.canEdit" class="research-form" @submit.prevent="submit"><p class="eyebrow">DRAFT AN ACTION</p><h2>新的触达方案</h2><label>方案名称<input v-model="name" required minlength="2"></label><label>目标研究群组<select v-model="segment"><option v-for="s in store.segments" :key="s.id" :value="s.id">研究 #{{s.run_id}} · {{s.name}} · {{s.size}} 位</option></select></label><label>行动与复盘说明<textarea v-model="note" rows="5" maxlength="1000"></textarea></label><button class="primary" :disabled="busy||!segment">保存待批准方案 →</button><p class="muted">这里只生成站内交付名单，不会向客户发送消息。</p></form><section class="campaign-list"><article v-for="c in store.campaigns" :key="c.id" class="campaign-item"><div class="section-title"><span class="eyebrow">ACTION NOTE / {{String(c.id).padStart(3,'0')}}</span><StatusBadge :status="c.status"/></div><h2>{{c.name}}</h2><p class="campaign-audience">{{c.segment_name}} <b>{{c.size}} 位匿名客户</b></p><p>{{c.note}}</p><div class="campaign-actions"><button v-if="c.status==='draft'&&auth.user?.role==='admin'" class="outline" :disabled="busy" @click="approve(c.id)">批准交付 ✓</button><button v-if="c.status==='approved'" class="text-button" :disabled="busy" @click="perform(()=>exportCampaign(c.id))">下载匿名名单 CSV ↓</button><small v-else>等待运营负责人批准</small></div></article><EmptyState v-if="!store.campaigns.length" title="还没有触达方案" text="先完成一次分群研究，再选择一个群组建立行动计划。"/></section></div></template>
